from collections import Counter
import sys

def read_scrambled_flags(filename):
    # Read noisy/scrambled candidate flags from file
    flags = []
    with open(filename) as f:
        for line in f:
            cleaned = line.strip().replace('\r','').replace('\n','')
            # Only keep reasonable lines
            if 10 < len(cleaned) < 80:
                flags.append(cleaned)
    return flags

def freq_recover(flags, use_format_hint=True):
    if not flags:
        return ''
    # Pad all to the same length as most common line length
    length_counts = Counter(len(flag) for flag in flags)
    most_len, _ = length_counts.most_common(1)[0]
    flags = [flag for flag in flags if len(flag)==most_len]
    # Build columnar matrix
    columns = list(zip(*flags))
    recovered = []
    for idx, col in enumerate(columns):
        freq = Counter(col)
        candidates = freq.most_common()
        char = candidates[0][0]
        if use_format_hint and idx == 0 and char != 'f':
            # Enforce flag{
            char = 'f'
        elif use_format_hint and idx==1 and char != 'l':
            char = 'l'
        elif use_format_hint and idx==2 and char != 'a':
            char = 'a'
        elif use_format_hint and idx==3 and char != 'g':
            char = 'g'
        elif use_format_hint and idx==4 and char != '{':
            char = '{'
        elif use_format_hint and columns[-1][0] != '}':
            # Force last char to }
            if idx==len(columns)-1:
                char = '}'
        recovered.append(char)
    return ''.join(recovered)

def main():
    fn = sys.argv[1] if len(sys.argv)>1 else 'wrangle_flags_only.txt'
    flags = read_scrambled_flags(fn)
    res = freq_recover(flags)
    print(res)

if __name__ == '__main__':
    main()

