from collections import OrderedDict

scrambles = []
with open('/home/ctfplayer/ctf_files/scrambles.txt') as f:
    for line in f:
        # Only use lines with scrambled fragments containing {}
        if '{' in line or '}' in line:
            line = line.strip()
            if line:
                scrambles.append(line)

print('SCRAMBLES:')
for s in scrambles:
    print(s)

# Find curly-brace content and extract all unique characters across scrambles
curly_contents = []
for s in scrambles:
    matches = re.findall(r'\{([^}]*)\}', s)
    for m in matches:
        curly_contents.append(m)

print('\nFRAGMENTS IN CURLY:')
for c in curly_contents:
    print(c)
# Collect unique characters in curly fragments, preserve order
uniq = OrderedDict()
for frag in curly_contents:
    for ch in frag:
        if ch not in uniq:
            uniq[ch] = None

print('\nUNIQUE ORDERED CHARACTERS FROM CURLY:')
print(''.join(uniq.keys()))

import sys

def reverse_memfrob(s):
    # Apply XOR with 0x2a, 13 times per byte
    arr = bytearray(s)
    for _ in range(13):
        arr = bytearray([c ^ 0x2a for c in arr])
    return bytes(arr)

def main():
    # Read input outputs from stdin (one per line, hex encoded)
    outputs = [line.strip() for line in sys.stdin if line.strip()]
    recovered = []
    for out in outputs:
        b = bytes.fromhex(out)
        p = reverse_memfrob(b)
        recovered.append(p.decode(errors='replace'))
    for rec in recovered:
        print(rec)

if __name__ == "__main__":
    main()

